 "<span style=\"font-size:14px;color:#8a8270;letter-spacing:2px\">ASIENTO</span><br><b>Una página por diapositiva</b>": "<span style=\"font-size:14px;color:#8a8270;letter-spacing:2px\">SEAT</span><br><b>One page per slide</b>",
